// isNextOnNewLine determines whether the current token is on a different
// line (higher line number) than the next token. It handles imported
// tokens correctly. If there isn't a next token, it returns true.
func (d *Dispenser) isNextOnNewLine() bool {
	if d.cursor < 0 {
		return false
	}
	if d.cursor >= len(d.tokens)-1 {
		return true
	}

	curr := d.tokens[d.cursor]
	next := d.tokens[d.cursor+1]

	// If the next token is from a different file,
	// we can assume it's from a different line
	if curr.File != next.File {
		return true
	}

	// If the current token (incl line breaks) ends
	// on a line earlier than the next token,
	// then the next token is on a new line
	return curr.Line+curr.NumLineBreaks() < next.Line
}

func (d *Dispenser) loadLexer(input io.Reader) error {
	d.lexReader = bufio.NewReader(input)
	d.lexLine = 1
	d.lexSkippedLines = 0
	d.lexToken = Token{}
	d.resetLexerScanState()

	firstCh, _, err := d.lexReader.ReadRune()
	if err != nil {
		return err
	}
	if firstCh != 0xFEFF {
		if err := d.lexReader.UnreadRune(); err != nil {
			return err
		}
	}
	return nil
}

func (d *Dispenser) resetLexerScanState() {
	d.lexVal = nil
	d.lexComment = false
	d.lexQuoted = false
	d.lexBtQuoted = false
	d.lexInHeredoc = false
	d.lexHeredocEscaped = false
	d.lexEscaped = false
	d.lexHeredocMarker = ""
}

func (d *Dispenser) lexerMakeToken(quoted rune) bool {
	d.lexToken.Text = string(d.lexVal)
	d.lexToken.wasQuoted = quoted
	d.lexToken.heredocMarker = d.lexHeredocMarker
	return true
}

func (d *Dispenser) nextLexerToken() (bool, error) {
	d.resetLexerScanState()
	for {
		ch, _, err := d.lexReader.ReadRune()
		if err != nil {
			if len(d.lexVal) > 0 {
				if d.lexInHeredoc {
					return false, fmt.Errorf("incomplete heredoc <<%s on line #%d, expected ending marker %s", d.lexHeredocMarker, d.lexLine+d.lexSkippedLines, d.lexHeredocMarker)
				}
				return d.lexerMakeToken(0), nil
			}
			if err == io.EOF {
				return false, nil
			}
			return false, err
		}

		if !d.lexInHeredoc && !d.lexHeredocEscaped && len(d.lexVal) > 1 && string(d.lexVal[:2]) == "<<" {
			if ch == '<' {
				return false, fmt.Errorf("too many '<' for heredoc on line #%d; only use two, for example <<END", d.lexLine)
			}
			if ch == '\r' {
				continue
			}
			if ch == '\n' {
				d.lexHeredocMarker = string(d.lexVal[2:])
				if !heredocMarkerRegexp.Match([]byte(d.lexHeredocMarker)) {
					return false, fmt.Errorf("heredoc marker on line #%d must contain only alpha-numeric characters, dashes and underscores; got '%s'", d.lexLine, d.lexHeredocMarker)
				}
				d.lexInHeredoc = true
				d.lexSkippedLines++
				d.lexVal = nil
				continue
			}
			d.lexVal = append(d.lexVal, ch)
			continue
		}

		if d.lexInHeredoc {
			done, err := d.consumeLexerHeredoc(ch)
			if err != nil {
				return false, err
			}
			if done {
				return d.lexerMakeToken('<'), nil
			}
			continue
		}

		if !d.lexEscaped && !d.lexBtQuoted && ch == '\\' {
			d.lexEscaped = true
			continue
		}

		if d.lexQuoted || d.lexBtQuoted {
			if d.finishLexerQuoted(ch) {
				return d.lexerMakeToken(ch), nil
			}
			continue
		}

		if unicode.IsSpace(ch) {
			if d.consumeLexerSpace(ch) {
				return d.lexerMakeToken(0), nil
			}
			continue
		}

		if ch == '#' && len(d.lexVal) == 0 {
			d.lexComment = true
		}
		if d.lexComment {
			continue
		}

		if len(d.lexVal) == 0 {
			d.lexToken = Token{Line: d.lexLine}
			if ch == '"' {
				d.lexQuoted = true
				continue
			}
			if ch == '`' {
				d.lexBtQuoted = true
				continue
			}
		}

	if end != "" {
		parsed, err := strconv.Atoi(end)
		if err != nil {
			d.warnImportArg("Variadic placeholder "+token.Text+" has an invalid end index", token)
			return 0, 0, false
		}
		endIndex = parsed
	}
	return startIndex, endIndex, true
}

func (d *Dispenser) warnImportArg(message string, token Token) {
	caddy.Log().Named("caddyfile").Warn(
		message,
		zap.String("file", token.File+":"+strconv.Itoa(token.Line)),
		zap.Strings("import_chain", token.imports),
	)
}

func (d *Dispenser) makeImportArgsReplacer() *caddy.Replacer {
	d.argsRepl = caddy.NewEmptyReplacer()
	args := d.importArgs
	d.argsRepl.Map(func(key string) (any, bool) {
		if value, ok := d.lookupDeprecatedArg(key, args); ok {
			return value, true
		}
		if matches := argsRegexpIndexDeprecated.FindStringSubmatch(key); len(matches) > 0 {
			return nil, false
		}
		if value, ok := d.lookupIndexedArg(key, args); ok {
			return value, true
		}
		return nil, false
	})
	return d.argsRepl
}

func (d *Dispenser) lookupDeprecatedArg(key string, args []string) (any, bool) {
	if args == nil {
		args = d.importArgs
	}
	matches := argsRegexpIndexDeprecated.FindStringSubmatch(key)
	if len(matches) == 0 {
		return nil, false
	}
	value, err := strconv.Atoi(matches[1])
	if err != nil {
		caddy.Log().Named("caddyfile").Warn(
			"Placeholder {args." + matches[1] + "} has an invalid index")
		return nil, false
	}
	if value >= len(args) {
		caddy.Log().Named("caddyfile").Warn(
			"Placeholder {args." + matches[1] + "} index is out of bounds, only " + strconv.Itoa(len(args)) + " argument(s) exist")
		return nil, false
	}
	caddy.Log().Named("caddyfile").Warn(
		"Placeholder {args." + matches[1] + "} deprecated, use {args[" + matches[1] + "]} instead")
	return args[value], true
}

func (d *Dispenser) lookupIndexedArg(key string, args []string) (any, bool) {
	if args == nil {
		args = d.importArgs
	}
	matches := argsRegexpIndex.FindStringSubmatch(key)
	if len(matches) == 0 {
		return nil, false
	}
	if strings.Contains(matches[1], ":") {
		caddy.Log().Named("caddyfile").Warn(
			"Variadic placeholder {args[" + matches[1] + "]} must be a token on its own")
		return nil, false
	}
	value, err := strconv.Atoi(matches[1])
	if err != nil {
		caddy.Log().Named("caddyfile").Warn(
			"Placeholder {args[" + matches[1] + "]} has an invalid index")
		return nil, false
	}
	if value >= len(args) {
		caddy.Log().Named("caddyfile").Warn(
			"Placeholder {args[" + matches[1] + "]} index is out of bounds, only " + strconv.Itoa(len(args)) + " argument(s) exist")
		return nil, false
	}
	return args[value], true
}

func (d *Dispenser) ensureImportGraph() {
	if d.importNodes == nil {
		d.importNodes = make(map[string]bool)
	}
	if d.importEdges == nil {
		d.importEdges = make(adjacency)
	}
}

func (d *Dispenser) addImportNode(name string) {
	d.ensureImportGraph()
	if _, exists := d.importNodes[name]; exists {
		return
	}
	d.importNodes[name] = true
}

func (d *Dispenser) addImportNodes(names []string) {
	d.ensureImportGraph()
	for _, name := range names {
		d.addImportNode(name)
	}
}

func (d *Dispenser) removeImportNode(name string) {
	delete(d.importNodes, name)
}

func (d *Dispenser) removeImportNodes(names []string) {
	if d.importNodes == nil {
		return
	}
	for _, name := range names {
		d.removeImportNode(name)
	}
}

func (d *Dispenser) importNodeExists(key string) bool {
	_, exists := d.importNodes[key]
	return exists
}

func (d *Dispenser) importsAreConnected(from, to string) bool {
	al, ok := d.importEdges[from]
	if !ok {
		return false
	}
	for _, v := range al {
